@torch.no_grad()
def p_match(item, l=None, vec=None, system=None):
    x = tok(chat(item["question"], system), return_tensors="pt").input_ids
    start = x.shape[1] - 3       # '<|im_start|>', 'assistant', newline
    def hook(m, a, o):
        resid(o)[:, start:] += vec          # in place, post-instruction only
        return o
    h = layers[l].register_forward_hook(hook) if vec is not None else None
    logits = model(x).logits[0, -1]
    if h: h.remove()
    p = logits.softmax(-1)
    pa, pb = p[TOK_A].item(), p[TOK_B].item()
    a_is_match = item["answer_matching_behavior"].strip().startswith("(A")
    return (pa if a_is_match else pb) / (pa + pb)

def mean_p(items, **kw):
    return sum(p_match(i, **kw) for i in items) / len(items)

sweep = {l: (mean_p(val, l=l, vec=-4 * V[l]), mean_p(val, l=l, vec=4 * V[l]))
         for l in range(6, 21)}
best = max(sweep, key=lambda l: sweep[l][1] - sweep[l][0])     # layer 14

v = V[best]; v_hat = v / v.norm()
r = torch.randn(v.shape[0], generator=torch.Generator().manual_seed(0))
r = r / r.norm() * v.norm()                  # random direction, same norm

@torch.no_grad()
def next_logprobs(q, vec=None, ablate=None):
    x = tok(chat(q), return_tensors="pt").input_ids; start = x.shape[1] - 3
    def add(m, a, o):
        resid(o)[:, start:] += vec; return o
    def abl(m, a, o):                         # directional ablation
        h = resid(o); h -= (h @ ablate).unsqueeze(-1) * ablate; return o
    hs = [layers[best].register_forward_hook(add)] if vec is not None else []
    if ablate is not None:                    # after every decoder layer
        hs += [L.register_forward_hook(abl) for L in layers]
    out = model(x).logits[0, -1].log_softmax(-1)
    for h in hs: h.remove()
    return out

def kl(q, **kw):                              # KL(original || edited)
    p0, p1 = next_logprobs(q), next_logprobs(q, **kw)
    return (p0.exp() * (p0 - p1)).sum().item()
